cd /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/revivalpage/rebuild && cat > shot.js <<'EOF'
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>body{margin:0;font-family:system-ui}</style></head><body>' + fs.readFileSync('page.html','utf8') + '</body></html>';
  const browser = await chromium.launch();
  for (const [name,w,h] of [['phone',400,850],['desktop',1400,900]]) {
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    await page.setContent(html, { waitUntil: 'load' });
    await page.waitForTimeout(500);
    const sw = await page.evaluate(() => document.documentElement.scrollWidth);
    const open = await page.evaluate(() => document.querySelector('details.words') && document.querySelector('details.words').open);
    console.log(name, 'scrollWidth', sw, 'glossary open', open);
    await page.screenshot({ path: 'shot-' + name + '.png' });
    await page.close();
  }
  await browser.close();
})();
EOF
node shot.js 2>&1 | tail -3

